#!/bin/bash
# SYBNB auth/session e2e runner — generated by Claude 2026-10-15 (v2: + fixtures + payment-policy env).
# Runs against a DISPOSABLE Neon test database (sybnb-e2e-test) — NOT production.
set -u
cd "$(dirname "$0")"

export DATABASE_URL="${DATABASE_URL:?set DATABASE_URL in your shell (test DB only)}"
export AUTH_SECRET='e2e-test-auth-secret-0123456789abcdef0123456789abcdef'
export PHONE_HASH_SECRET='e2e-test-phone-hash-secret-0123456789abcdef01234567'
export OTP_EXPOSE_FOR_TEST=true
export SYBNB_COUNTRY=syria
export STORAGE_ALLOW_LOCAL=true
export API_PORT=3051
export API_BASE=http://127.0.0.1:3051

# Payment-policy env (mirrors scripts/run-all-e2e.sh — default-deny gates opened for tests)
export PAYMENT_WEBHOOK_SECRET="${PAYMENT_WEBHOOK_SECRET:-}"
export STRIPE_WEBHOOK_SECRET="${STRIPE_WEBHOOK_SECRET:-}"
export STRIPE_SECRET_KEY="${STRIPE_SECRET_KEY:-}"
export PAYMENTS_ENABLED=true
export PAYMENT_INTENTS_ENABLED=true
export PAYMENT_RAIL_MANUAL_PROOF_ENABLED=true
export PAYMENT_POLICY_TEST_COUNTRY_ELIGIBLE=true
export PAYMENT_POLICY_ELIGIBLE_DIVISIONS=STAYS,RENTALS,BUY,CARS,MARKETPLACE,NEW_CONSTRUCTION,PLATFORM,SR
for op in PAYMENT_INTENT_CREATE PAYMENT_INTENT_CAPTURE PAYMENT_INTENT_REFUND PAYMENT_INTENT_REPLAY \
          PAYMENT_INTENT_WEBHOOK_INTAKE PAYMENT_INTENT_WEBHOOK_APPLY PAYMENT_INTENT_RECONCILIATION_READ \
          STRIPE_CHECKOUT_CREATE STRIPE_CHECKOUT_CAPTURE STRIPE_CHECKOUT_WEBHOOK_INTAKE \
          STRIPE_CHECKOUT_WEBHOOK_APPLY STRIPE_CHECKOUT_RECONCILIATION_READ \
          MANUAL_PROOF_CREATE MANUAL_PROOF_CAPTURE MANUAL_PROOF_REFUND MANUAL_PROOF_PAYOUT_RELEASE \
          MANUAL_PROOF_RECONCILIATION_READ MANUAL_PROOF_LEGACY_REFUND_ACCEPT MANUAL_PROOF_REFUND_REQUEST; do
  export "PAYMENT_OPERATION_${op}_ENABLED=true"
done

# Shared fixture ids (same defaults as scripts/run-all-e2e.sh)
export SELLER1=1fdde54d-20f1-41ae-9f9a-2a4482f13c69
export SELLER2=f845e528-dff8-404f-b9ef-6f096fefd9c5
export BUYER=b2cf0295-8b24-4be0-a014-8b9321c44e0a
export ADMIN=c6b57605-18aa-4093-bd99-264185de4b26
export HOST=480b860e-f32f-4089-a34b-5bbeec33952f
export GUEST=e14887c6-6fff-4cab-bcea-62e1b976ea61
export GUEST2=ec554c79-c1e4-451a-b65c-206486a5a491

LOG=e2e-results.log
: > "$LOG"
say() { echo "$@" | tee -a "$LOG"; }

if lsof -iTCP:3051 -sTCP:LISTEN >/dev/null 2>&1; then
  say "ERROR: port 3051 is already in use by:"; lsof -iTCP:3051 -sTCP:LISTEN | tee -a "$LOG"; exit 1
fi

say "== prisma migrate deploy (Neon test DB) =="
npx prisma migrate deploy >> "$LOG" 2>&1 || { say "MIGRATE FAILED — see $LOG"; exit 1; }

say "== seed shared e2e fixtures =="
node scripts/ci-seed-e2e-fixtures.mjs >> "$LOG" 2>&1 || { say "SEED FAILED — see $LOG"; exit 1; }

say "== mark fixture hosts verified (migration 049 gate) =="
node --input-type=module -e "
import { db, disconnectDb } from './server/lib/prisma.mjs'
const ids = [process.env.HOST, process.env.SELLER1, process.env.SELLER2]
await db().user.updateMany({ where: { id: { in: ids }, hostVerifiedAt: null }, data: { hostVerifiedAt: new Date() } })
await disconnectDb()
" >> "$LOG" 2>&1 || { say "HOST VERIFY STEP FAILED — see $LOG"; exit 1; }

say "== starting API =="
node server/index.mjs >> api-e2e.log 2>&1 &
API_PID=$!
trap 'kill $API_PID 2>/dev/null' EXIT
for i in $(seq 1 30); do
  curl -s -o /dev/null http://127.0.0.1:3051/api/health && break
  sleep 1
done
curl -s -o /dev/null http://127.0.0.1:3051/api/health || { say "API FAILED TO START — see api-e2e.log"; exit 1; }
say "API up (pid $API_PID)"

SUITES="signup-journey host-login-journey email-otp otp-identity session-revocation admin-self-review-protection commit-boundary-reauthorization"
OVERALL=0
for s in $SUITES; do
  say ""
  say "=============== SUITE: $s ==============="
  node "tests/e2e/$s.e2e.mjs" >> "$LOG" 2>&1
  rc=$?
  [ $rc -ne 0 ] && OVERALL=1
  say "--- exit code: $rc ---"
done

say ""
say "== DONE — overall: $([ $OVERALL -eq 0 ] && echo ALL SUITES PASSED || echo SOME SUITES FAILED) =="
exit $OVERALL
